}

tool_input.new_string:
/** 与 Figma Make 参考站 http://localhost:8443/ 逐像素对齐的静态 UI。远程数据模式下必须走真实页，否则历史/填报会被写死的演示数据替换。 */
export function isRef8443(): boolean {
  const mode = (import.meta.env.VITE_DATA_MODE as string | undefined) ?? ''
  if (mode === 'remote') return false
  const flag = (import.meta.env.VITE_UI_REF8443 as string | undefined) ?? ''
  return flag === 'true' || flag === '1'
}
